import{ativarMascaras}from"./modules/formularios.js";function ativarFormulario(){const e=document.getElementById("form-cadastro");e&&e.addEventListener("submit",function(t){if(t.preventDefault(),!e.checkValidity())return void e.reportValidity();const n={nome:document.getElementById("nome").value,email:document.getElementById("email").value,nascimento:document.getElementById("nascimento").value,cpf:document.getElementById("cpf").value,telefone:document.getElementById("telefone").value,cep:document.getElementById("cep").value,endereco:document.getElementById("endereco").value};localStorage.setItem("cadastro",JSON.stringify(n))})}function carregarCadastro(){const e=localStorage.getItem("cadastro");if(e){const t=JSON.parse(e);document.getElementById("nome").value=t.nome,document.getElementById("email").value=t.email,document.getElementById("nascimento").value=t.nascimento,document.getElementById("cpf").value=t.cpf,document.getElementById("telefone").value=t.telefone,document.getElementById("cep").value=t.cep,document.getElementById("endereco").value=t.endereco}}const telefone=document.getElementById("telefone");telefone&&telefone.addEventListener("input",function(){let e=telefone.value.replace(/\D/g,"");e=e.replace(/^(\d{2})(\d)/,"($1) $2"),e=e.replace(/(\d{5})(\d{1,4})$/,"$1-$2"),telefone.value=e});const cep=document.getElementById("cep");cep&&cep.addEventListener("input",function(){let e=cep.value.replace(/\D/g,"");e=e.replace(/^(\d{5})(\d)/,"$1-$2"),cep.value=e});const abrirModal=document.querySelector(".abrir-modal"),fecharModal=document.querySelector(".fechar-modal"),modal=document.querySelector(".modal");function criarCadastro(){return'\n    <form id="form-cadastro">\n        <fieldset>\n    <legend>Dados pessoais</legend>\n\n    <label for="nome">Nome completo:</label>\n    <input type="text" id="nome" name="nome" required>\n\n    <label for="email">E-mail:</label>\n    <input type="email" id="email" name="email" required>\n\n    <label for="nascimento">Data de nascimento:</label>\n    <input type="date" id="nascimento" name="nascimento" required>\n    <label for="cpf">CPF:</label>\n<input type="text" id="cpf" name="cpf"\n    pattern="[0-9]{3}.[0-9]{3}.[0-9]{3}-[0-9]{2}" required>\n\n<label for="telefone">Telefone:</label>\n<input type="tel" id="telefone" name="telefone"\n    pattern="\\([0-9]{2}\\) [0-9]{5}-[0-9]{4}" required>\n\n</fieldset>\n\n<fieldset>\n    <legend>Endereço</legend>\n\n    <label for="cep">CEP:</label>\n    <input type="text" id="cep" name="cep"\n        pattern="[0-9]{5}-[0-9]{3}" required>\n\n    <label for="endereco">Endereço:</label>\n    <input type="text" id="endereco" name="endereco" required>\n</fieldset>\n\n<button type="submit">Enviar cadastro</button>\n</form>\n'}function ativarMenuHamburguer(){const e=document.querySelector(".menu-hamburguer"),t=document.getElementById("menu-principal");e&&t&&e.addEventListener("click",function(){const n=t.classList.toggle("menu-aberto");e.setAttribute("aria-expanded",n)})}abrirModal&&fecharModal&&modal&&(abrirModal.addEventListener("click",function(){modal.classList.add("ativo")}),fecharModal.addEventListener("click",function(){modal.classList.remove("ativo")}));const linksPagina=document.querySelectorAll("[data-pagina]"),conteudo=document.getElementById("conteudo"),paginaInicio=conteudo?conteudo.innerHTML:"";linksPagina.forEach(function(e){e.addEventListener("click",function(t){t.preventDefault();const n=e.dataset.pagina;document.title="Projeto ReConecta - "+e.textContent.trim(),"inicio"===n&&(conteudo.innerHTML=paginaInicio),"projetos"===n&&(conteudo.innerHTML=criarProjetos()),"cadastro"===n&&(conteudo.innerHTML=criarCadastro(),ativarMascaras(),ativarFormulario(),carregarCadastro())})});const projetos=[{titulo:"Doações",descricao:"As doações ajudam o Projeto ReConecta a recuperar equipamentos eletrônicos."},{titulo:"Voluntariado",descricao:"Os voluntários participam das ações do projeto e contribuem com a inclusão digital."}];function criarProjetos(){let e="";return projetos.forEach(function(t){e+=`\n            <section>\n                <h2>${t.titulo}</h2>\n                <p>${t.descricao}</p>\n            </section>\n        `}),e}ativarMascaras(),ativarFormulario(),ativarMenuHamburguer();